arguments.command:
cd /workspace && find submission -type d -name __pycache__ -exec rm -rf {} + 2>/dev/null; python3 - <<'PYEOF'
import os, stat
root='/workspace/submission'
files=entries=total=0; bad=[]
for base,dirs,names in os.walk(root):
    for n in dirs+names:
        p=os.path.join(base,n); st=os.lstat(p); entries+=1
        if not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode)): bad.append(('special',p))
        if stat.S_ISREG(st.st_mode):
            files+=1; total+=st.st_size
            if st.st_nlink!=1: bad.append(('nlink',p))
            if st.st_size>256*1024: bad.append(('big',p))
print('files',files,'entries',entries,'bytes',total,'issues',bad)
print('main.py present:', os.path.isfile(os.path.join(root,'main.py')))
PYEOF
source dev.sh && python3 check.py submission
